-- Candidatory neutral operations and RBAC foundation; applied to remote D1 on 2026-10-27
PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS workspaces(id TEXT PRIMARY KEY,name TEXT NOT NULL CHECK(length(name) BETWEEN 2 AND 120),jurisdiction TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended','archived')),created_by INTEGER NOT NULL REFERENCES candidate_users(telegram_id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS workspace_members(workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,telegram_id INTEGER NOT NULL REFERENCES candidate_users(telegram_id),role TEXT NOT NULL CHECK(role IN ('owner','admin','editor','member','auditor')),status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','disabled')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(workspace_id,telegram_id));
CREATE INDEX IF NOT EXISTS idx_member_user ON workspace_members(telegram_id,status);
CREATE TABLE IF NOT EXISTS admin_audit(id TEXT PRIMARY KEY,workspace_id TEXT,actor_id INTEGER NOT NULL,action TEXT NOT NULL,record_type TEXT NOT NULL,record_id TEXT NOT NULL DEFAULT '',detail TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_audit_workspace ON admin_audit(workspace_id,created_at DESC);
CREATE TABLE IF NOT EXISTS workspace_tasks(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,title TEXT NOT NULL CHECK(length(title) BETWEEN 2 AND 240),description TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'todo' CHECK(status IN ('todo','doing','done')),priority TEXT NOT NULL DEFAULT 'normal' CHECK(priority IN ('low','normal','high')),due_date TEXT,assignee_id INTEGER REFERENCES candidate_users(telegram_id),created_by INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_tasks_ws ON workspace_tasks(workspace_id,status,due_date);
CREATE TABLE IF NOT EXISTS workspace_events(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,title TEXT NOT NULL CHECK(length(title) BETWEEN 2 AND 240),starts_at TEXT NOT NULL,location TEXT NOT NULL DEFAULT '',description TEXT NOT NULL DEFAULT '',created_by INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_events_ws ON workspace_events(workspace_id,starts_at);
CREATE TABLE IF NOT EXISTS public_commitments(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,title TEXT NOT NULL CHECK(length(title) BETWEEN 2 AND 240),description TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','review','published','completed')),evidence_link TEXT NOT NULL DEFAULT '',created_by INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_commitments_ws ON public_commitments(workspace_id,status);
CREATE TABLE IF NOT EXISTS workspace_expenses(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,description TEXT NOT NULL,amount_minor INTEGER NOT NULL CHECK(amount_minor>=0),currency TEXT NOT NULL DEFAULT 'IRR',category TEXT NOT NULL DEFAULT 'general',spent_at TEXT NOT NULL,created_by INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_expenses_ws ON workspace_expenses(workspace_id,spent_at);
CREATE TABLE IF NOT EXISTS content_revision_requests(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,title TEXT NOT NULL,body TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','review','approved','rejected')),created_by INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_content_ws ON content_revision_requests(workspace_id,status);